func (q *Queries) ListClientUsersForErasure(ctx context.Context, clientID *uuid.UUID) ([]ListClientUsersForErasureRow, error) {
	rows, err := q.db.Query(ctx, listClientUsersForErasure, clientID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListClientUsersForErasureRow{}
	for rows.Next() {
		var i ListClientUsersForErasureRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.AvatarUrl,
			&i.DisabledAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listInactiveUsers = `-- name: ListInactiveUsers :many
SELECT u.id, u.email::text AS email, u.firstname, btrim(u.firstname || ' ' || u.lastname) AS label
FROM users u
WHERE u.deleted_at IS NULL AND u.role NOT IN ('admin', 'bot')
  AND coalesce(u.last_login_at, u.created_at) < $1::timestamptz
  AND NOT EXISTS (
      SELECT 1 FROM rgpd_erasures e
      WHERE e.subject_type = 'user' AND e.subject_id = u.id AND e.status IN ('scheduled', 'running')
  )
ORDER BY u.id
LIMIT $2
`

type ListInactiveUsersParams struct {
	Cutoff time.Time `json:"cutoff"`
	Batch  int32     `json:"batch"`
}

type ListInactiveUsersRow struct {
	ID        uuid.UUID `json:"id"`
	Email     string    `json:"email"`
	Firstname string    `json:"firstname"`
	Label     string    `json:"label"`
}

// Comptes non administrateurs sans connexion depuis `cutoff`, qui n'ont pas
// deja un effacement en cours.
func (q *Queries) ListInactiveUsers(ctx context.Context, arg ListInactiveUsersParams) ([]ListInactiveUsersRow, error) {
	rows, err := q.db.Query(ctx, listInactiveUsers, arg.Cutoff, arg.Batch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListInactiveUsersRow{}
	for rows.Next() {
		var i ListInactiveUsersRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.Firstname,
			&i.Label,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listOtherScheduledErasuresOfUser = `-- name: ListOtherScheduledErasuresOfUser :many
SELECT e.id, e.subject_type, e.subject_id, e.subject_label, e.reason, e.status, e.scheduled_for, e.requested_by, e.cancelled_by, e.cancelled_at, e.executed_at, e.summary, e.error, e.prev_disabled, e.created_at, e.updated_at FROM rgpd_erasures e
WHERE e.status = 'scheduled' AND e.reason = 'request' AND e.id <> $1::uuid
  AND (
      (e.subject_type = 'user' AND e.subject_id = $2::uuid)
      OR (e.subject_type = 'client' AND e.subject_id = (SELECT u.client_id FROM users u WHERE u.id = $2::uuid))
  )
ORDER BY e.created_at, e.id
FOR UPDATE
`

